}"},{"rank":2,"score":44.7915,"file_path":"internal/cli/facts_proposals_cmd.go","start_line":175,"end_line":203,"focus_line":175,"snippet_start_line":175,"snippet_end_line":203,"symbol_start_line":175,"symbol_end_line":203,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/facts_proposals_cmd.go:function:resolveHostedProposalTarget","symbol_name":"resolveHostedProposalTarget","qualified_name":"resolveHostedProposalTarget","signature":"func resolveHostedProposalTarget(ctx context.Context, opts Options, pOpts factsProposalsOptions) (hostedProposalTarget, error)","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func resolveHostedProposalTarget(ctx context.Context, opts Options, pOpts factsProposalsOptions) (hostedProposalTarget, error) {
