	}
	return token, nil
}"},{"rank":5,"score":42.9597,"file_path":"internal/cli/connect_cmd.go","start_line":135,"end_line":150,"focus_line":138,"snippet_start_line":138,"snippet_end_line":150,"symbol_start_line":138,"symbol_end_line":150,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/connect_cmd.go:function:resolveHostedPlacement","symbol_name":"resolveHostedPlacement","qualified_name":"resolveHostedPlacement","signature":"func resolveHostedPlacement(ctx context.Context, runner CommandRunner, repoDir string) (hostedPlacement, error)","signals":["path","body","signature","symbol-name","constraint:entity","graph:callers","complete-symbol"],"snippet":"func resolveHostedPlacement(ctx context.Context, runner CommandRunner, repoDir string) (hostedPlacement, error) {
